window.SERU = (window.SERU || []).concat([
  // ---- Bolum 1 ----
  { s: 1, q: "Where should you keep your PHV driver's licence?",
    o: ["At home in a safe place, giving a copy to your operator", "In the vehicle's glovebox, so that you always have it with you", "With your operator, who must keep the original for you", "On the dashboard, where passengers can easily see it"],
    tr: "PHV sürücü lisansınızı nerede saklamalısınız?",
    e: "Lisansı evde güvenli bir yerde saklayın ve çalıştığınız operatör(ler)e bir kopyasını verin. Operatör hem PHV lisansınızın hem ehliyetinizin kopyasını tutmak zorunda.", ee: "Keep the licence at home in a safe place and give a copy to the operator or operators you work for. The operator must keep a copy of both your PHV licence and your driving licence." },
  { s: 1, q: "TfL has given you an exemption from wearing your badge. What must you do?",
    o: ["Carry the exemption notice with you at all times when working", "Show the exemption notice to TfL once a year at renewal", "Display the exemption notice on the outside of the vehicle", "Keep the exemption notice at home with your licence"],
    tr: "TfL size kart takma zorunluluğundan muafiyet verdi. Ne yapmalısınız?",
    e: "Muafiyet bildirgesini PHV sürücüsü olarak çalıştığınız her an yanınızda taşımalısınız.", ee: "You must carry the exemption notice with you at all times when you work as a PHV driver." },
  { s: 1, q: "What can happen if you do not comply with the conditions attached to your licence?",
    o: ["Your licence may be revoked", "You will receive a warning letter only", "Your operator will pay a fine for you", "Nothing, if you are a careful driver"],
    tr: "Lisansınıza eklenen koşullara uymazsanız ne olabilir?",
    e: "Koşullara uymazsanız lisansınız iptal edilebilir. Koşullar lisansla gelen mektupta açıklanır, o mektubu saklayın.", ee: "If you do not follow the conditions, your licence can be revoked. The conditions are explained in the letter that comes with the licence, so keep that letter." },
  { s: 1, q: "Which of these drivers may be exempt from supplying a medical form?",
    o: ["A driver with a current London taxi driver's licence", "A driver who has never had any medical problems", "A driver who is younger than 30 years of age", "A driver who has a letter from their own doctor"],
    tr: "Bu sürücülerden hangisi sağlık formu vermekten muaf olabilir?",
    e: "Muafiyet: geçerli Londra taksi sürücü lisansı, tam veya geçici (Ocak 1997 sonrası) DVLA Group 2 ehliyeti ya da JAA pilot lisansı olanlar.", ee: "Exemptions: a current London taxi driver's licence, a full or provisional DVLA Group 2 driving licence (issued after January 1997), or a JAA pilot's licence." },
  { s: 1, q: "Who is responsible for making sure the medical form is completed and returned to TfL?",
    o: ["You, the driver", "Your doctor", "Your operator", "The DVLA"],
    tr: "Sağlık formunun doldurulup TfL'e gönderilmesinden kim sorumludur?",
    e: "Formun bir doktor tarafından eksiksiz doldurulmasından ve TfL'e geri gönderilmesinden siz sorumlusunuz. Eksik bilgi lisans almamanıza yol açabilir.", ee: "You are responsible for making sure a doctor fills in the form completely and for sending it back to TfL. Missing information can mean you do not get a licence." },
  { s: 1, q: "You are disqualified from driving. What must you do?",
    o: ["Tell TfL immediately and return your PHV licence and badge", "Keep working until your court appeal has been decided", "Tell your operator and work only as a passenger assistant", "Wait for TfL to contact you before you do anything"],
    tr: "Araç kullanmaktan men edildiniz. Ne yapmalısınız?",
    e: "Hemen TfL'e bildirin ve PHV lisansınızı ve kartınızı iade edin.", ee: "Tell TfL immediately and return your PHV licence and badge." },
  { s: 1, q: "Another licensing authority suspends the taxi licence you hold with them. What should you do?",
    o: ["Tell TfL immediately", "Tell TfL at your next renewal", "Nothing - it is a different authority", "Tell only your operator"],
    tr: "Başka bir lisans otoritesindeki taksi lisansınız askıya alındı. Ne yapmalısınız?",
    e: "Başka bir otoritenin lisansınızı askıya alması, iptal etmesi veya başvurunuzu reddetmesi hemen TfL'e bildirilmeli.", ee: "If another authority suspends or revokes your licence, or refuses your application, you must tell TfL immediately." },
  { s: 1, q: "TfL writes to you about a complaint and asks for your comments. Why is it important to reply?",
    o: ["TfL can only make decisions based on the information it receives", "If you reply, TfL will always close the complaint straight away", "Replying means that your operator will deal with it instead", "It is not important, because TfL only acts on police reports"],
    tr: "TfL bir şikâyetle ilgili size yazıp görüşünüzü soruyor. Cevap vermek neden önemli?",
    e: "TfL kararlarını sadece eline geçen bilgiye göre verebilir. Cevap vermezseniz sizin tarafınız hiç dikkate alınmaz.", ee: "TfL can only make decisions based on the information it has. If you do not reply, your side will not be considered at all." },
  { s: 1, q: "What will an enhanced DBS check show?",
    o: ["Convictions, cautions, reprimands and final warnings", "Your credit history and any unpaid bills", "Your driving test results and lesson records", "Your employment history for the last ten years"],
    tr: "Gelişmiş (enhanced) DBS kontrolü neleri gösterir?",
    e: "Mahkûmiyetler, ihtarlar, kınamalar, son uyarılar; ayrıca polisin ilgili bilgileri ve savunmasız gruplarla çalışması yasak olanlar listesi.", ee: "Convictions, cautions, reprimands and final warnings. It also shows relevant police information and whether you are on the list of people barred from working with vulnerable groups." },
  { s: 1, q: "The address on your PHV driver's licence should be the same as the address on your...",
    o: ["DVLA driving licence", "bank statement", "operator's records", "council tax bill"],
    tr: "PHV sürücü lisansınızdaki adres hangi belgedeki adresle aynı olmalıdır?",
    e: "PHV lisansındaki adres DVLA ehliyetinizdeki adresle aynı olmalı. Taşınınca hem TfL'e (21 gün) hem DVLA'ya bildirin.", ee: "The address on your PHV licence must be the same as the address on your DVLA driving licence. When you move, tell both TfL (within 21 days) and the DVLA." },
  { s: 1, q: "If you own a PHV and your driver's licence is revoked, what may TfL also do?",
    o: ["Revoke the vehicle licence if there is a risk to public safety", "Sell the vehicle and give the money to your operator", "Transfer the vehicle licence to another driver automatically", "Nothing - the vehicle licence is always kept separate"],
    tr: "Aracın sahibiyseniz ve sürücü lisansınız iptal edilirse TfL başka ne yapabilir?",
    e: "Kamu güvenliği riski varsa (örneğin araç lisanssız biri tarafından PHV olarak kullanılabilecekse) araç lisansını da iptal edebilir.", ee: "If there is a risk to public safety (for example, if the vehicle could be used as a PHV by someone without a licence), TfL can also revoke the vehicle licence." },

  // ---- Bolum 2 ----
  { s: 2, q: "The licence discs on your PHV are damaged. Who should contact TfL?",
    o: ["The vehicle owner, immediately", "The operator, within 21 days", "The driver, at the next renewal", "Nobody, if they can still be read"],
    tr: "PHV aracınızın lisans diskleri hasar gördü. TfL ile kim iletişime geçmeli?",
    e: "Diskler hasar görür, kaybolur veya çalınırsa araç sahibi hemen TfL ile iletişime geçmeli ve yenisini istemeli.", ee: "If discs are damaged, lost or stolen, the vehicle owner must contact TfL straight away and ask for new ones." },
  { s: 2, q: "Your vehicle has an exemption from displaying licence discs. What must you, the driver, do?",
    o: ["Carry the exemption notice at all times when it is used as a PHV", "Display a handwritten sign in the window instead of the discs", "Tell each passenger about the exemption before they get in", "Nothing - the exemption is recorded on the TfL database"],
    tr: "Aracınızın lisans disklerini sergileme muafiyeti var. Sürücü olarak ne yapmalısınız?",
    e: "Araç PHV olarak kullanıldığı her an muafiyet bildirgesini yanınızda taşımalısınız.​‍‌⁠", ee: "You must carry the exemption notice with you at all times when the vehicle is used as a PHV.​‍‌⁠" },
  { s: 2, q: "A police officer asks for the insurance details of your PHV. What must you do?",
    o: ["Make the insurance details available to them", "Tell them to contact your operator instead", "Refuse unless you have been in a collision", "Give them your DVLA licence number only"],
    tr: "Polis PHV aracınızın sigorta bilgilerini istiyor. Ne yapmalısınız?",
    e: "Polis istediğinde sigorta bilgilerini sağlamalısınız. Sigorta bilgilerini araçta taşımanız veya sergilemeniz tavsiye edilir.", ee: "When the police ask, you must provide the insurance details. It is recommended that you keep the insurance details in the vehicle or display them." },
  { s: 2, q: "The manufacturer writes to you about a fault with your PHV. What should you do?",
    o: ["Read the letter carefully and follow its instructions", "Ignore it until the next licensing inspection", "Forward it to your operator and keep working", "Fix the fault yourself if it looks simple"],
    tr: "Üretici firma PHV aracınızdaki bir arıza hakkında size yazdı. Ne yapmalısınız?",
    e: "Mektubu dikkatle okuyup talimatlara uyun. TfL'den gelen bir mektup, araç onarılana kadar PHV olarak kullanılamayacağını da söyleyebilir.", ee: "Read the letter carefully and follow its instructions. A letter from TfL may also say that the vehicle cannot be used as a PHV until it is repaired." },
  { s: 2, q: "Before a new vehicle licence can be issued, what must happen?",
    o: ["The vehicle must have another licensing inspection", "The driver must pass the SERU assessment again", "The operator must send TfL a new booking record", "The vehicle must be sold to a new registered keeper"],
    tr: "Yeni bir araç lisansı verilmeden önce ne olmalıdır?",
    e: "Araç lisansı 1 yıl geçerlidir; yenisi için araç tekrar lisans muayenesinden geçmelidir.", ee: "A vehicle licence lasts 1 year. To get a new one, the vehicle must pass another licensing inspection." },
  { s: 2, q: "When must the hire or reward insurance be valid?",
    o: ["At all times when the vehicle is being used as a PHV", "Only when there is a passenger inside the vehicle", "Only during the hours shown on your operator's rota", "Only when the vehicle is driven inside Greater London"],
    tr: "Ücretli taşıma (hire or reward) sigortası ne zaman geçerli olmalıdır?",
    e: "Araç lisanslanırken ve PHV olarak kullanıldığı her an geçerli olmalıdır, iş beklerken de.", ee: "It must be valid when the vehicle is licensed and at all times when it is used as a PHV, including while you wait for work." },

  // ---- Bolum 3 ----
  { s: 3, q: "Your operator is licensed to take bookings at a nightclub. Where can it take bookings?",
    o: ["Only inside the venue, at the booking location on its licence", "Anywhere outside the venue, including on the pavement", "From drivers who wait in the street outside the venue", "At any pub or nightclub within one mile of the venue"],
    tr: "Operatörünüzün bir gece kulübünde iş alma lisansı var. İşleri nerede alabilir?",
    e: "Sadece mekânın içinde, lisansında belirtilen rezervasyon noktasında. Sürücüler kaldırımda veya mekân önünde müşteri arayamaz.", ee: "Only inside the venue, at the booking location named on its licence. Drivers cannot look for customers on the pavement or outside the venue." },
  { s: 3, q: "Outside a pub, a customer walks up and asks you for a ride home. What should you say?",
    o: ["They need to contact a licensed operator to make a booking", "You can take them if they pay the fare in cash before leaving", "You can take them if your operator agrees by phone afterwards", "They should wait by your car until you finish your break"],
    tr: "Bir pub'ın önünde bir müşteri yanınıza gelip eve götürmenizi istiyor. Ne demelisiniz?",
    e: "Rezervasyon yapmak için lisanslı bir operatöre başvurmasını söyleyin. Kaldırımda yolcu almak suç olabilir ve kovuşturulabilirsiniz.", ee: "Tell them to contact a licensed operator to make a booking. Picking up passengers on the pavement can be an offence and you could be prosecuted." },
  { s: 3, q: "While waiting near your operator's late-night venue, which of these is acceptable?",
    o: ["Waiting quietly with your engine switched off", "Leaving your engine running to keep warm", "Playing music loudly with the windows down", "Chatting loudly with other drivers in the street"],
    tr: "Operatörünüzün gece mekânının yakınında beklerken hangisi kabul edilebilir?",
    e: "Park, gürültü ve kendi davranışınızdan siz sorumlusunuz. Motoru çalışır bırakmayın, çöp atmayın, çevredeki sakinlere saygılı olun.", ee: "You are responsible for your parking, the noise and your own behaviour. Do not leave the engine running, do not drop litter and be respectful to local residents." },
  { s: 3, q: "Can you carry out a booking where the destination is outside Greater London?",
    o: ["Yes, if the booking was accepted by a licensed London PHV operator", "No, London PHVs must stay inside Greater London at all times", "Only if the passenger pays a TfL out-of-area fee in advance", "Only if you also hold a licence from the other local council"],
    tr: "Varış yeri Büyük Londra dışında olan bir işi yapabilir misiniz?",
    e: "Evet. İş lisanslı bir Londra PHV operatörü tarafından kabul edildiyse alış ve/veya varış noktası Londra dışında olabilir. Şüphe varsa operatöre sorun.", ee: "Yes. If a licensed London PHV operator accepted the job, the pick-up and/or the destination can be outside London. If you are in doubt, ask your operator." },
  { s: 3, q: "Your passenger disagrees with the fare at the end of the journey. What should you have done?",
    o: ["Checked with your operator beforehand what to do in this situation", "Agreed to whatever amount the passenger says they want to pay", "Refused to let the passenger leave until the fare is paid in full", "Called the police straight away to report the passenger"],
    tr: "Yolculuk sonunda yolcu ücrete itiraz ediyor. Önceden ne yapmış olmalıydınız?",
    e: "Yolcu ücrete itiraz ederse veya ödeyemezse ne yapacağınızı ve fiş (receipt) düzenini önceden operatörünüze sormalısınız.", ee: "If a passenger disagrees with the fare or cannot pay, you should have asked your operator in advance what to do. You should also ask about the receipt arrangements." },
  { s: 3, q: "Which of these does your operator NOT have to record about a booking?",
    o: ["The passenger's date of birth", "The main destination", "The agreed or estimated fare", "The vehicle's registration number"],
    tr: "Operatörünüz bir iş hakkında hangisini kaydetmek ZORUNDA DEĞİLDİR?",
    e: "Operatör şunları kaydeder: işin tarihi, yolcunun adı, alış saati ve yeri, ana varış yeri, ücret, sürücü ve aracın kimliği. Doğum tarihi listede yok.", ee: "The operator records: the date of the booking, the passenger's name, the pick-up time and place, the main destination, the fare, and the identity of the driver and vehicle. Date of birth is not on the list." },
  { s: 3, q: "You report a suspicious person to the anti-terrorist hotline but worry you are wasting police time. What does the handbook say?",
    o: ["Don't worry - the police will decide if the information is important", "Only call if you are completely certain that a crime will happen", "Call your operator first, so they can decide whether to report it", "You must give your full name, or the police cannot use the report"],
    tr: "Şüpheli birini terörle mücadele hattına bildiriyorsunuz ama polisin vaktini harcamaktan endişeleniyorsunuz. El kitabı ne diyor?",
    e: "Endişelenmeyin. Bilginin önemli olup olmadığına polis karar verir ve bilgiyi gizli tutar. Hat: 0800 789 321.", ee: "Do not worry. The police decide whether the information is important, and they keep it confidential. The hotline is 0800 789 321." },
  { s: 3, q: "When must you tell your operator about extra luggage or extra passengers?",
    o: ["As soon as it is safe to do so", "Only at the end of the journey", "Only if the passenger complains", "Only if the fare will be lower"],
    tr: "Ekstra bagaj veya ekstra yolcuyu operatörünüze ne zaman bildirmelisiniz?",
    e: "Varış yeri değişikliği, ekstra yolcu veya bagajı güvenli olduğu ilk anda bildirin ki operatör ücreti güncelleyebilsin.", ee: "Tell your operator about a change of destination, extra passengers or luggage as soon as it is safe to do so, so that the operator can update the fare." },
  { s: 3, q: "You have agreed to carry out a booking. When can you decide not to do it?",
    o: ["Only if you have a very good reason", "Whenever a better booking comes in", "If the passenger lives too far away", "If you would rather finish early"],
    tr: "Bir işi yapmayı kabul ettiniz. Ne zaman yapmamaya karar verebilirsiniz?",
    e: "Kabul ettiğiniz işi çok iyi bir nedeniniz yoksa yapmalısınız. Reddederseniz kibarca açıklayın ve operatöre tam nedenini söyleyin.", ee: "You must do a booking you have accepted unless you have a very good reason. If you refuse, explain politely and tell your operator the exact reason." },

  // ---- Bolum 4 ----
  { s: 4, q: "Which of these should reduce the risk of a disagreement with a passenger?",
    o: ["Being clear about the route, journey time and fare before you start", "Choosing the route yourself without telling the passenger about it", "Asking the passenger for the fare in cash before they get into the car", "Keeping the conversation to a minimum so you are not distracted"],
    tr: "Yolcuyla anlaşmazlık riskini hangisi azaltır?",
    e: "Yola çıkmadan önce nereye gideceğinizi, rotayı, süreyi ve ücreti açıkça konuşmak anlaşmazlık riskini azaltır.", ee: "Talking clearly about where you are going, the route, the journey time and the fare before you set off lowers the risk of a disagreement." },
  { s: 4, q: "A passenger becomes aggressive and violent. Who should you tell immediately?",
    o: ["Your operator, giving the passenger's name and address if you know it", "TfL, using the online complaints form within seven days of the journey", "Your insurance company, so that they can prepare for a possible claim", "Nobody, unless the passenger actually hurts you or damages your car"],
    tr: "Bir yolcu saldırgan ve şiddetli hale geliyor. Hemen kime haber vermelisiniz?",
    e: "Hemen operatörünüze bildirin ve biliyorsanız yolcunun tam adını ve adresini verin. Acil durumda 999'u arayın.", ee: "Tell your operator immediately and give the passenger's full name and address if you know them. In an emergency, call 999." },
  { s: 4, q: "An unconscious passenger becomes aggressive when the ambulance is on its way. What should you do?",
    o: ["Move somewhere safe, but where you can still see the person", "Lock the passenger inside the vehicle until help arrives", "Leave the area and let the emergency services deal with it", "Hold the passenger down so that they cannot hurt anyone"],
    tr: "Ambulans yoldayken baygın yolcu kendine gelip saldırganlaşıyor. Ne yapmalısınız?",
    e: "Kendiniz için güvenli ama kişiyi görebileceğiniz bir yere geçin. Önce kendi güvenliğinizi düşünün.", ee: "Move to a place that is safe for you but where you can still see the person. Think about your own safety first." },
  { s: 4, q: "After a violent incident, what does the handbook suggest?",
    o: ["Talk about it with a friend, colleague or your operator", "Keep it to yourself so it does not affect your work", "Go straight back to work to forget about it quickly", "Only tell your family, and never tell your operator"],
    tr: "Şiddet içeren bir olaydan sonra el kitabı ne öneriyor?",
    e: "Olayı bir arkadaş, meslektaş veya operatörünüzle konuşun, destek olup olmadığını öğrenin ve tekrar olmaması için bildirin.", ee: "Talk about the incident with a friend, a colleague or your operator, find out whether support is available, and report it so it does not happen again." },
  { s: 4, q: "When recording an assault, which detail should you include?",
    o: ["A description of the attacker and any witnesses", "The amount you earned during that shift", "The music that was playing in the car", "The passenger's rating on the booking app"],
    tr: "Bir saldırıyı kaydederken hangi ayrıntıyı eklemelisiniz?",
    e: "Ne zaman ve nerede oldu, saldırganın tarifi, yolcu olup olmadığı, olayın kısa anlatımı, tanıklar, olay türü, yaralanmalar ve hemen ne yapıldığı.", ee: "When and where it happened, a description of the attacker, whether they were a passenger, a short account of the incident, witnesses, the type of incident, any injuries and what was done straight away." },
  { s: 4, q: "How can CCTV in your vehicle help you?",
    o: ["It may reduce violence and could lower your insurance premium", "It means you never need to report incidents to the police", "It allows you to refuse passengers without any explanation", "It replaces the need to tell your operator about problems"],
    tr: "Araçtaki CCTV size nasıl yardımcı olabilir?",
    e: "CCTV tehdit ve şiddeti azaltabilir. Kayıt anlaşmazlıklarda delil olduğu için sigorta primini de düşürebilir.", ee: "CCTV can reduce threats and violence. The recording is evidence in disputes, so it can also lower your insurance premium." },
  { s: 4, q: "An incident happens while you are away from your vehicle. What should you do afterwards?",
    o: ["Get to your vehicle and take time to calm down before driving", "Drive away immediately as fast as you can to escape the area", "Stay where you are and wait for the attacker to calm down", "Go back to work straight away and report it at the weekend"],
    tr: "Aracınızdan uzaktayken bir olay yaşanıyor. Sonrasında ne yapmalısınız?",
    e: "Mümkün olunca aracınıza dönün ve yola çıkmadan önce sakinleşmek için zaman tanıyın.", ee: "Go back to your vehicle as soon as you can and give yourself time to calm down before you drive." },
  { s: 4, q: "Why is it helpful to have a pre-planned way to excuse yourself from a difficult situation?",
    o: ["It can help you leave the situation without making it worse", "It means you can avoid ever reporting the incident to anyone", "It allows you to charge the passenger an extra fee for trouble", "It shows the passenger that you are the one who is in charge"],
    tr: "Zor bir durumdan çıkmak için önceden planlanmış bir yolunuz olması neden faydalıdır?",
    e: "Durumu kötüleştirmeden çıkmanızı sağlar. Örnek: 'Ben yardımcı olamıyorum ama gideceğimiz adresteki biri sorununuzu çözebilir.'", ee: "It lets you leave without making the situation worse. Example: ‘I cannot help you, but someone at the address we are going to may be able to solve your problem.’" },

  // ---- Bolum 5 ----
  { s: 5, q: "What may happen if there is a pattern of poor behaviour and all attempts to improve it have failed?",
    o: ["TfL may suspend or revoke your licence", "Your operator must pay a fine to TfL", "You will have to retake the topographical test", "Nothing, as long as no crime was committed"],
    tr: "Kötü davranış bir alışkanlık haline gelmişse ve düzeltme girişimleri başarısız olduysa ne olabilir?",
    e: "Ciddi bir şikâyet, çok sayıda şikâyet veya düzelmeyen kötü davranış örüntüsü varsa TfL lisansı askıya alabilir veya iptal edebilir.", ee: "If there is a serious complaint, many complaints, or a pattern of poor behaviour that does not improve, TfL can suspend or revoke the licence." },
  { s: 5, q: "A passenger is not happy with how your operator dealt with their complaint. What can they do?",
    o: ["Contact TfL, which may carry out its own investigation", "Nothing - the operator's decision is always final", "Only take the operator to court for a refund", "Ask the driver to pay compensation directly"],
    tr: "Yolcu, operatörün şikâyetini ele alış biçiminden memnun değil. Ne yapabilir?",
    e: "Yolcu TfL'e başvurabilir; TfL kendi soruşturmasını yapabilir. Yolcular doğrudan polise veya TfL'e de başvurabilir.", ee: "The passenger can contact TfL, and TfL may carry out its own investigation. Passengers can also go directly to the police or to TfL." },
  { s: 5, q: "A passenger offers sexual activity instead of paying the fare. What should you do?",
    o: ["Refuse - offering or accepting sex in place of a fare is never allowed", "Accept, as long as it happens after the journey has finished", "Accept, but tell your operator that the fare was not paid", "Refuse, but only because you would prefer to be paid in cash"],
    tr: "Bir yolcu ücret yerine cinsel ilişki teklif ediyor. Ne yapmalısınız?",
    e: "Ücret yerine cinsel ilişki teklif etmek veya kabul etmek asla kabul edilemez. Lisansınızı kaybedersiniz ve polis soruşturabilir.", ee: "Offering or accepting sex instead of a fare is never acceptable. You will lose your licence and the police may investigate." },
  { s: 5, q: "Is it acceptable to watch or share sexual pictures while working as a PHV driver?",
    o: ["No, never", "Yes, if no passenger is in the car", "Yes, if the passenger agrees", "Yes, on a break"],
    tr: "PHV sürücüsü olarak çalışırken cinsel içerikli görüntü izlemek veya paylaşmak kabul edilebilir mi?",
    e: "Hayır. Pornografik veya cinsel içerikli materyal izlemek, göstermek veya paylaşmak asla kabul edilemez.", ee: "No. Watching, showing or sharing pornographic or sexual material is never acceptable." },
  { s: 5, q: "Which of these could make a passenger feel uncomfortable and must be avoided?",
    o: ["Staring at any part of their body", "Asking if the temperature is OK", "Confirming the destination", "Offering help with luggage"],
    tr: "Hangisi yolcuyu rahatsız edebilir ve kaçınılması gerekir?",
    e: "Yolcunun vücudunun herhangi bir yerine bakmak, görünüşü veya kıyafeti hakkında yorum yapmak, cinsel içerikli konuşma asla yapılmaz.", ee: "Staring at any part of the passenger's body, commenting on their appearance or clothes, and sexual talk must never be done." },
  { s: 5, q: "You meant to be friendly, but a passenger felt your behaviour was sexual. What does the handbook say?",
    o: ["Avoid any behaviour that might be understood as sexual, whatever your intentions", "It is fine, because your intentions were good and you meant no harm", "The passenger should have told you during the journey if they were unhappy", "It only matters if the passenger makes a complaint to the police"],
    tr: "Samimi olmak istediniz ama yolcu davranışınızı cinsel algıladı. El kitabı ne diyor?",
    e: "Niyetiniz ne kadar iyi olursa olsun, cinsel olarak anlaşılabilecek her davranıştan kaçının. Davranışınızın yolcuyu nasıl etkileyeceğini düşünün.", ee: "However good your intentions, avoid any behaviour that could be understood as sexual. Think about how your behaviour will affect the passenger." },

  // ---- Bolum 6 ----
  { s: 6, q: "A road sign shows that access is for taxis only. Can a PHV use the road?",
    o: ["No - a PHV is not a taxi", "Yes, if carrying a passenger", "Yes, outside the rush hour", "Yes, if the PHV is electric"],
    tr: "Bir trafik işareti girişin sadece taksilere açık olduğunu gösteriyor. PHV bu yolu kullanabilir mi?",
    e: "Hayır. PHV taksi değildir; 'taxi' yazan erişim işaretleri PHV'leri kapsamaz.", ee: "No. A PHV is not a taxi, so access signs that say ‘taxi’ do not apply to PHVs." },
  { s: 6, q: "Your passenger needs help to get to their front door. There are waiting restrictions. What should you do?",
    o: ["Spend only a short time away and note the booking details in case of a PCN", "Leave the car there for as long as needed, because helping passengers is allowed", "Refuse to help, because you can never leave your vehicle on a yellow line", "Ask the passenger to pay any parking fine that you might receive afterwards"],
    tr: "Yolcunuzun kapısına kadar yardıma ihtiyacı var. Bekleme kısıtlaması olan bir yerdesiniz. Ne yapmalısınız?",
    e: "Genel bir izin yok, ama bazı belediyeler bunu işin parçası olarak kabul ediyor. Mümkün olduğunca kısa süre uzaklaşın ve olası bir PCN'e karşı yolcu/iş bilgilerini not edin.", ee: "There is no general permission, but some councils treat this as part of the job. Be away for as short a time as possible and note the passenger and booking details in case you get a PCN." },
  { s: 6, q: "You arrive early for a booking and wait on a single yellow line during restricted hours. What could happen?",
    o: ["You may get a PCN, even though you are waiting for a booked passenger", "Nothing, because PHVs are allowed to wait on yellow lines for bookings", "Nothing, as long as you stay in the driver's seat with the engine running", "You will only get a warning, because you arrived early for the booking"],
    tr: "Bir işe erken geldiniz ve kısıtlama saatlerinde tek sarı çizgide bekliyorsunuz. Ne olabilir?",
    e: "PCN alabilirsiniz. Kısıtlamalı yerlerde sadece yolcu binip inerken durabilirsiniz; erken gelmek veya yolcunun geç kalması bekleme izni vermez.", ee: "You may get a PCN. In restricted places you can only stop while passengers get in or out. Arriving early, or the passenger being late, does not give you permission to wait." },
  { s: 6, q: "On a red route you see a parking bay marked with a 'P'. What can you do there?",
    o: ["Park or wait, as long as you obey the time limits on the signs", "Nothing - PHVs can never use red route parking bays", "Park for as long as you like, because it is a parking bay", "Only drop off passengers - waiting is never allowed"],
    tr: "Kırmızı rotada 'P' işaretli bir park yeri görüyorsunuz. Orada ne yapabilirsiniz?",
    e: "Tabeladaki süre sınırlarına uyduğunuz sürece park edebilir, bekleyebilir, yolcu alıp indirebilirsiniz.", ee: "You can park, wait, and pick up and drop off passengers, as long as you obey the time limits shown on the signs." },
  { s: 6, q: "Where must you never stop, for any reason, on a red route?",
    o: ["Within a pedestrian clearway", "In a marked 'P' parking bay", "On a single red line at night", "Beside a red route bus lane"],
    tr: "Kırmızı rotada hiçbir nedenle nerede duramazsınız?",
    e: "Yaya geçiş alanı (pedestrian clearway), zikzak çizgiler, geniş kırmızı çizgili otobüs durakları ve engel/tehlike yaratacağınız her yer.", ee: "The pedestrian clearway, zig-zag lines, bus stops with a wide red line, and anywhere you would cause an obstruction or a danger." },
  { s: 6, q: "How can you usually work out the emissions standard of your vehicle?",
    o: ["From the first registration date on the V5C", "From the size of the engine on the MOT", "From the colour of the vehicle licence disc", "From the age of the tyres on the vehicle"],
    tr: "Aracınızın emisyon standardını genelde nasıl öğrenebilirsiniz?",
    e: "Emisyon standardı genelde V5C belgesindeki ilk tescil tarihinden anlaşılır.", ee: "You can usually tell the emissions standard from the first registration date on the V5C document." },
  { s: 6, q: "When you pick up a passenger in a bus lane, how should you enter and leave it?",
    o: ["In the most direct and safe way, watching for cyclists", "Slowly, by driving along the bus lane for a short way", "Quickly, without indicating, to avoid delaying buses", "Only by reversing into it from a side road nearby"],
    tr: "Otobüs şeridinde yolcu alırken şeride nasıl girip çıkmalısınız?",
    e: "En kısa ve güvenli şekilde girip çıkın. Otobüs şeridini kullanabilen bisiklet ve motosikletlilere, otobüsten inip karşıya geçen yayalara dikkat edin.", ee: "Enter and leave in the shortest and safest way. Watch for cyclists and motorcyclists who can use the bus lane, and for pedestrians getting off a bus and crossing the road." },
  { s: 6, q: "What can happen if you park or wait on a taxi rank?",
    o: ["You may be fined and your licence could be suspended or revoked", "Nothing, if you move as soon as a taxi arrives at the rank", "You will receive a warning letter from the local council", "Your operator will be fined, but you will not be affected"],
    tr: "Taksi durağına park ederseniz veya beklerseniz ne olabilir?",
    e: "Para cezası alabilirsiniz; TfL de lisansınızı askıya alma veya iptal dahil işlem yapabilir.", ee: "You may get a fine, and TfL may take action, including suspending or revoking your licence." },
  { s: 6, q: "Is a wheelchair accessible PHV registered with TfL exempt from the ULEZ charge?",
    o: ["Yes", "No", "Only at night", "Only if electric"],
    tr: "TfL'de tekerlekli sandalyeye uygun olarak kayıtlı PHV, ULEZ ücretinden muaf mıdır?",
    e: "Evet, TfL tarafından tekerlekli sandalyeye uygun olarak kayıtlı PHV'ler ULEZ ücretinden muaftır.", ee: "Yes. PHVs registered with TfL as wheelchair accessible are exempt from the ULEZ charge." },

  // ---- Bolum 7 ----
  { s: 7, q: "What happens to the risk of a collision as your speed increases?",
    o: ["You have less time to react and injuries become more serious", "You spend less time on the road, so the risk becomes lower", "Nothing changes, as long as you stay within the speed limit", "Only the risk to your passengers increases, not to others"],
    tr: "Hızınız arttıkça çarpışma riski nasıl değişir?",
    e: "Hız arttıkça kazadan kaçınmak için daha az zamanınız olur ve yaralanmalar ağırlaşır. Hız sınırı içinde ve koşullara uygun hızda gidin.", ee: "The faster you go, the less time you have to avoid a collision, and injuries become more serious. Drive within the speed limit and at a speed that suits the conditions." },
  { s: 7, q: "Who tests drivers for drugs and alcohol at the roadside?",
    o: ["The police", "TfL officers", "Your operator", "Your insurer"],
    tr: "Yol kenarında sürücülere uyuşturucu ve alkol testini kim yapar?",
    e: "Polis yol kenarında uyuşturucu ve alkol testi yapar. Alkol veya uyuşturucu etkisindeyken asla araç kullanmayın.", ee: "The police test for drugs and alcohol at the roadside. Never drive under the influence of alcohol or drugs." },
  { s: 7, q: "An adult passenger does not want to wear a seatbelt. What should you do?",
    o: ["Encourage them to wear it for their own safety", "Ignore it, because it is the passenger's choice", "Refuse to start until you fasten it for them", "Ask them to sit in the boot area instead"],
    tr: "Yetişkin bir yolcu emniyet kemeri takmak istemiyor. Ne yapmalısınız?",
    e: "Tüm yetişkinler kemer takmalı; sürücü yetişkin yolcuları kendi güvenlikleri için kemer takmaya teşvik etmeli. 14 yaş altı çocuklardan ise sürücü sorumlu.", ee: "All adults should wear a seatbelt. The driver should encourage adult passengers to wear one for their own safety. The driver is responsible for children under 14." },
  { s: 7, q: "There is no correct child seat for a five-year-old. How can the child travel?",
    o: ["On a rear seat, wearing an adult seat belt", "On the front seat, wearing an adult seat belt", "On a rear seat, without wearing any seat belt", "On an adult's lap, sharing the adult's belt"],
    tr: "Beş yaşındaki bir çocuk için uygun çocuk koltuğu yok. Çocuk nasıl seyahat edebilir?",
    e: "Uygun koltuk yoksa çocuk arka koltukta gider: 3 yaş ve üstü yetişkin kemeriyle, 3 yaş altı kemersiz.", ee: "If there is no suitable seat, the child travels on a rear seat: with an adult seatbelt if aged 3 or over, and without a seatbelt if under 3." },
  { s: 7, q: "Why should you take extra care when driving at night?",
    o: ["Pedestrians, cyclists and motorcyclists may be harder to see", "There are always more speed cameras on London roads at night", "Passengers are more likely to complain about the fare at night", "Traffic lights in London work differently after midnight"],
    tr: "Gece araç kullanırken neden ekstra dikkatli olmalısınız?",
    e: "Gece yayalar, bisikletliler ve motosikletliler daha zor görülür.", ee: "At night, pedestrians, cyclists and motorcyclists are harder to see." },
  { s: 7, q: "When should you use your indicators?",
    o: ["When turning or changing lanes, even if you think no one is near", "Only when there are other vehicles directly behind you", "Only when there are cyclists or pedestrians nearby", "Only at junctions with traffic lights or roundabouts"],
    tr: "Sinyal lambalarınızı ne zaman kullanmalısınız?",
    e: "Dönerken veya şerit değiştirirken, yakında kimse olmadığını düşünseniz bile sinyal verin; erken verin ve manevradan sonra kapatın.", ee: "Signal when you turn or change lanes, even if you think no one is nearby. Signal early and turn the indicator off after the manoeuvre." },
  { s: 7, q: "When you start the engine, a driver warning light stays on. What does this mean?",
    o: ["There may be a fault that needs to be checked", "The vehicle is ready and safe to drive", "The licence disc needs to be replaced", "The seatbelt reminder is working well"],
    tr: "Motoru çalıştırdığınızda bir uyarı lambası yanık kalıyor. Bu ne anlama gelir?",
    e: "Sürücü kontrolü: motor çalıştırıldığında uyarı lambaları yanık kalmamalı. Yanık kalıyorsa kontrol edilmesi gereken bir arıza olabilir.", ee: "This is a driver check: warning lights should not stay on after the engine starts. If one stays on, there may be a fault that needs to be checked." },
  { s: 7, q: "Which of these must be in the passenger compartment of a PHV?",
    o: ["Seat belts fitted to all passenger seats", "A first aid kit for every passenger", "A printed map of Greater London", "A card machine for paying fares"],
    tr: "PHV'nin yolcu bölümünde hangisi bulunmalıdır?",
    e: "Tüm yolcu koltuklarında emniyet kemeri; ayrıca temiz döşeme, iç ışıklar, çalışan kapı ve kilitler, ısıtma ve sigara içilmez işaretleri.", ee: "Seat belts must be fitted to all passenger seats. There must also be clean upholstery, interior lights, working doors and locks, heating, and no-smoking signs." },
  { s: 7, q: "Before driving, you notice oil on the ground under your vehicle. What should you do?",
    o: ["Get the leak checked - fluids should not leak from the vehicle", "Ignore it, because a small amount of oil is completely normal", "Drive to your first booking and check it at the end of the day", "Cover it with sand and carry on with your shift as normal"],
    tr: "Yola çıkmadan aracınızın altında yerde yağ görüyorsunuz. Ne yapmalısınız?",
    e: "Araç dışı kontrol: aracın altından yere sıvı (yağ, fren hidroliği) sızmamalı. Sızıntıyı kontrol ettirin.​‍‌⁠", ee: "This is an outside check: no fluid (oil, brake fluid) should leak onto the ground under the vehicle. Get the leak checked.​‍‌⁠" },
  { s: 7, q: "Which of these is allowed on your vehicle's windows?",
    o: ["Approved signage only", "Any advertising stickers", "Your operator's posters", "Large tinted film strips"],
    tr: "Aracınızın camlarında hangisine izin verilir?",
    e: "Camlar temiz, hasarsız ve onaylanmamış işaret veya reklamlardan arınmış olmalıdır.", ee: "Windows must be clean and undamaged, and free of any signs or adverts that are not approved." },
  { s: 7, q: "Your tyre has a bulge on its side wall. What should you do?",
    o: ["Replace the tyre - tyres must be free from lumps and bulges", "Keep driving, but check the tyre again in a week's time", "Add more air so that the bulge becomes less visible", "Drive more slowly until your next licensing inspection"],
    tr: "Lastiğinizin yanağında bir şişlik var. Ne yapmalısınız?",
    e: "Lastikler kesik, şişlik, yırtık ve aşırı veya düzensiz aşınmadan arınmış olmalı. Lastiği değiştirin.", ee: "Tyres must be free from cuts, lumps, bulges, tears and heavy or uneven wear. Replace the tyre." },
  { s: 7, q: "Traffic is stopped. Should you still check for cyclists and pedestrians?",
    o: ["Yes - they may still be moving even when most vehicles are stopped", "No - when the traffic is stopped, everyone else will also be stopped", "Only if you are planning to open your door to let a passenger out", "Only if you are in a bus lane where cyclists are allowed to ride"],
    tr: "Trafik durmuş. Yine de bisikletli ve yayaları kontrol etmeli misiniz?",
    e: "Evet. Araçların çoğu dursa bile bisikletliler, yayalar ve motosikletliler hareket ediyor olabilir.", ee: "Yes. Even when most vehicles are stopped, cyclists, pedestrians and motorcyclists may still be moving." },
  { s: 7, q: "What kind of offence is careless or dangerous driving?",
    o: ["A serious offence with heavy penalties", "A minor offence with only a warning", "A civil matter between two drivers", "Not an offence if no one is injured"],
    tr: "Dikkatsiz veya tehlikeli sürüş ne tür bir suçtur?",
    e: "Dikkatsiz veya tehlikeli sürüş ağır cezaları olan ciddi bir suçtur.", ee: "Careless or dangerous driving is a serious offence with heavy penalties." },

  // ---- Bolum 8 ----
  { s: 8, q: "You offer help to an older passenger. What should you do next?",
    o: ["Wait for your offer to be accepted and listen to their requests", "Start helping straight away, because older people always need help", "Help them in the same way that you help every other passenger", "Ask their companion what help they need instead of asking them"],
    tr: "Yaşlı bir yolcuya yardım teklif ettiniz. Sonra ne yapmalısınız?",
    e: "Teklifinizin kabul edilmesini bekleyin ve isteklerini dinleyin; herkes farklıdır.", ee: "Wait for your offer to be accepted and listen to their requests. Everyone is different." },
  { s: 8, q: "A passenger has difficulty hearing. How can you help?",
    o: ["Face them so they can see your lips as you speak", "Turn the radio up so they can hear the journey", "Speak only to the person travelling with them", "Avoid talking to them during the whole journey"],
    tr: "Bir yolcunun işitme güçlüğü var. Nasıl yardımcı olabilirsiniz?",
    e: "Dudaklarınızı görebilmesi için yüzünüzü ona dönün, net ve yüksek sesle konuşun ya da yazın. Yanınızda kalem ve kâğıt bulundurun.", ee: "Face them so they can see your lips, and speak clearly and loudly, or write. Keep a pen and paper with you." },
  { s: 8, q: "You arrive at the destination with a vision-impaired passenger. What should you do?",
    o: ["Tell them the location, offer help and guide them to a safe place", "Open their door and drive away as soon as they get out of the car", "Leave them at the kerb, because they know where they are going", "Ask a passer-by in the street to help them to their front door"],
    tr: "Görme engelli bir yolcuyla varış yerine geldiniz. Ne yapmalısınız?",
    e: "Neresi olduğunu söyleyin, araçtan inmesi için yardım teklif edin ve ayrılmadan önce onu güvenli bir yere yönlendirin.", ee: "Say where you are, offer help to get out of the vehicle, and guide them to a safe place before you leave." },
  { s: 8, q: "If you drive a designated wheelchair accessible vehicle, what must be true of its equipment?",
    o: ["It must be in good working order and ready to use at any time", "It only needs to be checked once a year at the licensing inspection", "It can be removed when you are not expecting wheelchair users", "It must only be used by the passenger, never by the driver"],
    tr: "Tekerlekli sandalyeye uygun kayıtlı bir araç kullanıyorsanız ekipmanı nasıl olmalıdır?",
    e: "Ekipman iyi çalışır durumda ve her an kullanıma hazır olmalıdır.", ee: "The equipment must be in good working order and ready to use at any time." },
  { s: 8, q: "Where must you display an exemption notice for carrying wheelchairs or assistance dogs?",
    o: ["In the windscreen of your vehicle", "On your PHV driver's badge", "On your operator's website", "On the rear passenger door"],
    tr: "Tekerlekli sandalye veya yardımcı köpek taşıma muafiyet bildirgesini nerede sergilemelisiniz?",
    e: "Muafiyet sadece tıbbi nedenle verilir; TfL'den alınan bildirge aracın ön camında sergilenir.", ee: "An exemption is given only for a medical reason. The notice you get from TfL is displayed in the windscreen of the vehicle." },
  { s: 8, q: "How can you always tell that a dog is an assistance dog?",
    o: ["You cannot always tell - not all assistance dogs wear a jacket", "It will always be wearing a coloured jacket with a logo on it", "It will always be a Labrador or a Golden Retriever breed", "The passenger must show you a TfL card for the dog first"],
    tr: "Bir köpeğin yardımcı köpek olduğunu her zaman nasıl anlarsınız?",
    e: "Her zaman anlayamazsınız. Yeleğin rengi bazen hangi tür yardım verdiğini gösterir ama her yardımcı köpek yelek giymez ve hepsi aynı cins değildir.", ee: "You cannot always tell. The colour of the jacket sometimes shows what kind of help the dog gives, but not every assistance dog wears a jacket and they are not all the same breed." },
  { s: 8, q: "What will TfL do if there is enough evidence that a driver broke the Equality Act?",
    o: ["Prosecute the driver if it is in the public interest", "Send the driver on a free customer service course", "Ask the operator to deal with it privately", "Nothing, unless the passenger was injured"],
    tr: "Bir sürücünün Eşitlik Yasası'nı çiğnediğine dair yeterli kanıt varsa TfL ne yapar?",
    e: "Yeterli kanıt varsa ve kamu yararına ise TfL her zaman kovuşturur. Mahkûmiyet halinde lisans askıya alınabilir veya iptal edilebilir.", ee: "If there is enough evidence and it is in the public interest, TfL will prosecute. If the driver is convicted, the licence can be suspended or revoked." },
  { s: 8, q: "In 2002, what did the Shariat Council confirm about assistance dogs?",
    o: ["They may travel in PHVs driven by Muslims", "They must travel in the boot of the vehicle", "Muslim drivers are exempt from carrying them", "They can only travel with a written permit"],
    tr: "Şeriat Konseyi 2002'de yardımcı köpekler hakkında neyi onayladı?",
    e: "Eğitimli yardımcı köpeklerin, Müslümanların yönettiği veya kullandığı PHV'lerde engelli kişilere eşlik edebileceğini onayladı.", ee: "It confirmed that trained assistance dogs may travel with disabled people in PHVs driven or operated by Muslims." },
  { s: 8, q: "A wheelchair user chooses to sit in a passenger seat. What must you do with the wheelchair?",
    o: ["Carry it safely and securely", "Leave it at the pick-up point", "Charge extra for carrying it", "Ask them to fold it on their lap"],
    tr: "Tekerlekli sandalye kullanan yolcu normal koltukta oturmayı seçiyor. Sandalyeyi ne yapmalısınız?",
    e: "Yolcu koltukta oturmayı seçerse tekerlekli sandalyeyi güvenli ve sabit şekilde taşımalısınız; ekstra ücret alınamaz.", ee: "If the passenger chooses to sit in a seat, you must carry the wheelchair safely and securely. You cannot charge extra." },
  { s: 8, q: "Which passengers in particular should be told about changes to the route?",
    o: ["Vision-impaired passengers and those with a learning disability", "Only passengers who are paying by cash at the end of the journey", "Only passengers who are travelling to an airport or a station", "Only passengers who ask you which way you are planning to go"],
    tr: "Rota değişiklikleri özellikle hangi yolculara söylenmelidir?",
    e: "Görme engelliler, yaşlılar ve öğrenme güçlüğü olan yolcular beklemedikleri rota değişikliklerinde endişelenebilir; onlara gecikme ve değişiklikleri söyleyin.", ee: "Vision-impaired passengers, elderly passengers and passengers with a learning disability may worry about route changes they do not expect. Tell them about delays and changes." },

  // ---- Bolum 9 ----
  { s: 9, q: "Who is an 'adult at risk'?",
    o: ["Anyone over 18 who needs extra care and support", "Anyone over 65 who travels without a companion", "Any adult travelling alone late at night", "Any adult who has drunk too much alcohol"],
    tr: "'Risk altındaki yetişkin' kimdir?",
    e: "Ekstra bakım ve desteğe ihtiyaç duyan 18 yaş üstü herkes. Yaş, engellilik veya ruhsal hastalık nedeniyle kendini koruyamayabilir.", ee: "Anyone over 18 who needs extra care and support. They may not be able to protect themselves because of age, disability or mental illness." },
  { s: 9, q: "Which of these could be a sign of child exploitation?",
    o: ["A young person being taken to a hotel at an odd time of night", "A teenager travelling to school with a group of their friends", "A parent asking you to drive carefully with their small child", "A young person asking you to change the radio station"],
    tr: "Hangisi çocuk sömürüsünün bir işareti olabilir?",
    e: "Gencin günün veya gecenin garip saatlerinde otele ya da genelev olduğundan şüphelenilen yere götürülmesi bir uyarı işaretidir.", ee: "It is a warning sign when a young person is taken, at a strange time of the day or night, to a hotel or to a place that you suspect is a brothel." },
  { s: 9, q: "A young passenger tells you they are going to meet someone they met online. Why might this be a concern?",
    o: ["It could be a sign that the young person is at risk", "It is never a concern, because meeting people online is normal", "It only matters if the young person is paying with cash", "It is a concern only because the fare might not be paid"],
    tr: "Genç bir yolcu internette tanıştığı biriyle buluşmaya gittiğini söylüyor. Bu neden endişe verici olabilir?",
    e: "Gencin tanımadığı, belki internette tanıştığı biriyle buluşmaya gitmesi risk işaretleri arasında sayılır.", ee: "A young person going to meet someone they do not know, perhaps someone they met online, is counted among the signs of risk." },
  { s: 9, q: "What does the handbook say about online safeguarding awareness training?",
    o: ["It is important that you take it", "It is only for operators' staff", "It is only for wheelchair drivers", "It is only needed for school runs"],
    tr: "El kitabı çevrim içi koruma farkındalık eğitimi hakkında ne diyor?",
    e: "Çevrim içi koruma (safeguarding) farkındalık eğitimi mevcut ve bu eğitimi almanız önemli.", ee: "Online safeguarding awareness training is available, and it is important that you take it." },
  { s: 9, q: "Which helpline would you use to report concerns about modern slavery?",
    o: ["The Modern Slavery Helpline", "The DVLA customer helpline", "Your operator's booking line", "The TfL lost property office"],
    tr: "Modern kölelik endişesini bildirmek için hangi hattı kullanırsınız?",
    e: "Modern Kölelik Yardım Hattı: 08000 121 700. Diğerleri: Crimestoppers (isimsiz) ve NSPCC. Kimliğinizi vermeden bildirebilirsiniz.", ee: "The Modern Slavery Helpline: 08000 121 700. Others are Crimestoppers (anonymous) and the NSPCC. You can report without giving your identity." },
  { s: 9, q: "A child at risk tells you about abuse. How should you behave?",
    o: ["Listen, and reassure them by being professional and kind", "Tell them you cannot get involved and change the subject", "Ask lots of detailed questions to find out everything", "Promise to keep it secret and not tell anyone at all"],
    tr: "Risk altındaki bir çocuk size istismardan bahsediyor. Nasıl davranmalısınız?",
    e: "Dinleyin, profesyonel, nazik ve düşünceli davranarak güven verin; sonra operatörünüze ve polise bildirin.", ee: "Listen, and reassure them by being professional, kind and thoughtful. Then report to your operator and the police." },
  { s: 9, q: "Whose responsibility is it to report a concern about a vulnerable adult?",
    o: ["Everyone's, including PHV drivers", "Only the police and social workers", "Only the vulnerable adult's family", "Only the PHV operator's managers"],
    tr: "Savunmasız bir yetişkinle ilgili endişeyi bildirmek kimin sorumluluğudur?",
    e: "Herkesin. Çocukları ve risk altındaki yetişkinleri korumak sadece sosyal hizmet uzmanlarının veya polisin işi değil.", ee: "Everyone's. Protecting children and adults at risk is not only the job of social workers or the police." },

  // ---- Bolum 10 ----
  { s: 10, q: "A passenger seems surprised when you stop to collect a second passenger. What may have happened?",
    o: ["They may have booked a ride-share by mistake", "They are not allowed to travel with strangers", "The second passenger has not paid their fare", "The operator has made the journey free of charge"],
    tr: "İkinci yolcuyu almak için durduğunuzda ilk yolcu şaşırıyor. Ne olmuş olabilir?",
    e: "Yolcu yanlışlıkla paylaşımlı yolculuk ayarlamış olabilir ve bu tartışmaya yol açabilir. Bu yüzden her yolcuya alırken paylaşımlı olduğunu teyit ettirin.", ee: "The passenger may have booked a ride-share by mistake, and this can cause an argument. That is why you should ask each passenger to confirm, when they get in, that it is a ride-share." },
  { s: 10, q: "During a rideshare you need to pick up a new passenger and change the route. What should you do?",
    o: ["Let the passengers know about the change", "Change the route without saying anything", "Ask the passengers to pay a little extra", "Drop off the first passenger early"],
    tr: "Paylaşımlı yolculukta yeni bir yolcu almanız ve rotayı değiştirmeniz gerekiyor. Ne yapmalısınız?",
    e: "Rotayı değiştirmeniz veya yeni yolcu almanız gerekirse yolculara bildirin.", ee: "If you need to change the route or pick up a new passenger, tell the passengers." },
  { s: 10, q: "A rideshare passenger feels uncomfortable. What might you suggest?",
    o: ["They can get out and arrange a non-rideshare PHV to meet them", "They should stay in the vehicle until the end of the journey", "They should swap seats with the other passenger in the car", "They should ask the other passenger to get out of the car"],
    tr: "Paylaşımlı yolculukta bir yolcu kendini rahatsız hissediyor. Ne önerebilirsiniz?",
    e: "Rahatsız hissederlerse inip rotanız üzerinde bir noktada paylaşımsız bir PHV ile buluşmayı ayarlayabileceklerini söylemek iyi bir fikir.", ee: "It is a good idea to tell them that, if they feel uncomfortable, they can get out and arrange to meet a non-rideshare PHV at a point along your route." },
  { s: 10, q: "Who should provide ridesharing training for PHV drivers?",
    o: ["The operator", "The passenger", "The council", "The DVLA"],
    tr: "PHV sürücülerine paylaşımlı yolculuk eğitimini kim vermelidir?",
    e: "Paylaşımlı yolculuk hizmeti veren operatörünüz bu eğitimi sağlamalıdır; operatörle konuşun.", ee: "Your operator, which provides the ridesharing service, should provide this training. Talk to your operator." },
  { s: 10, q: "Why can ridesharing put a passenger at risk?",
    o: ["Another passenger might learn their address and daily routine", "Ridesharing vehicles are not insured to carry more than one fare", "The driver is not allowed to talk to more than one passenger", "Passengers must sit next to each other in the back of the car"],
    tr: "Paylaşımlı yolculuk bir yolcuyu neden riske atabilir?",
    e: "Diğer yolcu ev adresini, iş yerini, günlük rutinini ve yalnız yaşayıp yaşamadığını öğrenebilir; bu da yolcuyu suça karşı savunmasız bırakabilir.", ee: "The other passenger may find out their home address, workplace and daily routine, and whether they live alone. This could make the passenger vulnerable to crime." },

  // ==== CUMLE TAMAMLAMA (ek) ====
  { t: "fill", s: 1, q: "You must tell TfL if you are on the Adults or Children's ___.",
    o: ["Barred Lists", "voting registers", "waiting lists", "council records"],
    tr: "Yetişkinler veya Çocuklar ___ yer alıyorsanız TfL'e bildirmelisiniz.",
    e: "Barred List: çocuklarla veya bazı yetişkinlerle çalışması yasaklanan kişilerin listesi. Bu listedeyseniz hemen TfL'e bildirin.", ee: "The Barred List is the list of people who are banned from working with children or with some adults. If you are on this list, tell TfL immediately." },
  { t: "fill", s: 1, q: "From the age of 45, you must have a medical examination each time you ___ your licence.",
    o: ["renew", "show", "copy", "use"],
    tr: "45 yaşından itibaren lisansınızı her ___ sağlık muayenesi olmalısınız.",
    e: "45 yaşından itibaren her yenilemede, 65 yaşından itibaren her yıl sağlık muayenesi gerekir.", ee: "From the age of 45 you need a medical examination every time you renew, and from the age of 65 you need one every year." },
  { t: "fill", s: 1, q: "If TfL becomes aware that you get frequent ___, it may take licensing action against you.",
    o: ["parking tickets", "phone calls", "good ratings", "bookings"],
    tr: "TfL sık sık ___ aldığınızı öğrenirse lisansınızla ilgili işlem yapabilir.",
    e: "Ceza puanı getirmeyen PCN ve park cezalarını bildirmeniz gerekmez ama sık alırsanız TfL işlem yapabilir.", ee: "You do not have to report PCNs and parking tickets that do not bring penalty points, but if you get them often, TfL may take action." },
  { t: "fill", s: 2, q: "Every PHV must have ___ insurance.",
    o: ["hire or reward", "social only", "commuting", "travel"],
    tr: "Her PHV'de ___ sigortası olmalıdır.",
    e: "Hire or reward (ücretli yolcu taşıma) sigortası; araç PHV olarak kullanıldığı her an geçerli olmalı.", ee: "Hire or reward insurance (insurance for carrying paying passengers). It must be valid whenever the vehicle is used as a PHV." },
  { t: "fill", s: 2, q: "The licence discs contain ___ features, so they will be damaged if you try to remove them.",
    o: ["security", "magnetic", "tracking", "heat-proof"],
    tr: "Lisans disklerinde ___ özellikleri vardır, bu yüzden sökmeye çalışırsanız hasar görürler.",
    e: "Disklerde güvenlik özellikleri var; sökmeye çalışmak onları kalıcı olarak bozar. Özel kullanımda da sökmeyin.", ee: "The discs have security features. Trying to remove them damages them permanently. Do not remove them, even for private use." },
  { t: "fill", s: 3, q: "You must not give any sign to a member of the public that suggests you are ___ without a booking.",
    o: ["available for hire", "a careful driver", "a London resident", "on a break"],
    tr: "Rezervasyon olmadan halka ___ olduğunuzu düşündürecek hiçbir işaret vermemelisiniz.",
    e: "Rezervasyonsuz kiralanabilir olduğunuzu ima eden işaret veya söz yasak; halkı size yaklaşmaya teşvik etmeyin.", ee: "Any sign or words suggesting that you can be hired without a booking are forbidden. Do not encourage the public to approach you." },
  { t: "fill", s: 3, q: "Airports are private property and can make their own rules, called ___.",
    o: ["byelaws", "statutes", "contracts", "licences"],
    tr: "Havalimanları özel mülktür ve ___ denen kendi kurallarını koyabilir.",
    e: "Havalimanları taksi ve PHV'ler için kendi kurallarını (byelaws) koyabilir. Heathrow'un kendi byelaw'ları var.", ee: "Airports can make their own rules (byelaws) for taxis and PHVs. Heathrow has its own byelaws." },
  { t: "fill", s: 3, q: "By law, your operator must keep a record of any items of ___ they hold.",
    o: ["lost property", "fuel receipts", "driver photos", "spare parts"],
    tr: "Yasaya göre operatörünüz elindeki ___ kaydını tutmak zorundadır.",
    e: "Bulunan eşyayı operatöre götürün; operatör kayıt tutmak zorunda.", ee: "Take any item you find to the operator. The operator must keep a record." },
  { t: "fill", s: 4, q: "Offensive or violent behaviour towards you because of your race or faith is a ___.",
    o: ["hate crime", "civil dispute", "parking offence", "customer complaint"],
    tr: "Irkınız veya inancınız nedeniyle size yönelik saldırgan veya şiddetli davranış bir ___ dır.",
    e: "Nefret suçu. Polise 101'den, acil durumda 999'dan bildirin.", ee: "It is a hate crime. Report it to the police on 101, or on 999 in an emergency." },
  { t: "fill", s: 4, q: "If you feel concerned about a passenger, act immediately - the earlier you notice a problem, the more ___ you have.",
    o: ["choices", "money", "passengers", "bookings"],
    tr: "Bir yolcudan endişeleniyorsanız hemen harekete geçin; sorunu ne kadar erken fark ederseniz o kadar çok ___ olur.",
    e: "İçgüdülerinize güvenin; sorunu erken fark etmek, ondan kaçınmak için daha fazla seçenek demektir.", ee: "Trust your instincts. Noticing a problem early means you have more choices to avoid it." },
  { t: "fill", s: 5, q: "No type of sexual behaviour between you and a passenger is ever acceptable, even if ___.",
    o: ["both of you agree to it", "the journey has ended", "it is outside London", "you are not working"],
    tr: "Sizinle yolcu arasında hiçbir cinsel davranış, ___ bile kabul edilemez.",
    e: "İki taraf da razı olsa bile asla kabul edilemez; lisans kaybı ve polis soruşturması getirir.", ee: "It is never acceptable, even if both people agree. It leads to loss of your licence and a police investigation." },
  { t: "fill", s: 5, q: "You should never make comments or jokes about someone's age, race, religion, ___.",
    o: ["disability or sexual orientation", "favourite food or taste in music", "shoes, bags or handbag colours", "journey time or choice of route"],
    tr: "Birinin yaşı, ırkı, dini, ___ hakkında asla yorum veya şaka yapmamalısınız.",
    e: "Yaş, ırk, din, engellilik, cinsel yönelim veya cinsiyet kimliği hakkında yorum ya da şaka yapılmaz.", ee: "Do not make comments or jokes about age, race, religion, disability, sexual orientation or gender identity." },
  { t: "fill", s: 6, q: "PHV drivers must not stop on ___ lines, for example by pedestrian crossings or outside schools.",
    o: ["zig-zag", "single red", "single yellow", "white dashed"],
    tr: "PHV sürücüleri örneğin yaya geçitlerinde veya okul önlerinde ___ çizgilerde duramaz.",
    e: "Zikzak çizgilerde durmak her zaman yasak.", ee: "Stopping on zig-zag lines is always forbidden." },
  { t: "fill", s: 6, q: "You can get a PCN for moving traffic offences such as an illegal ___.",
    o: ["U-turn", "indicator", "seatbelt", "headlight"],
    tr: "Yasadışı ___ gibi hareketli trafik ihlalleri için PCN alabilirsiniz.",
    e: "Otobüs şeridinde gitmek, yasak dönüşler (örneğin yasadışı U dönüşü) ve sarı kutu kavşağı kapatmak PCN sebebidir.", ee: "Driving in a bus lane, banned turns (for example, an illegal U-turn) and blocking a yellow box junction can all lead to a PCN." },
  { t: "fill", s: 6, q: "On red routes, you cannot stop at bus stops marked with a wide ___ line by the kerb.",
    o: ["red", "white", "blue", "green"],
    tr: "Kırmızı rotalarda kaldırım kenarında geniş ___ çizgiyle işaretli otobüs duraklarında duramazsınız.",
    e: "Geniş kırmızı çizgili otobüs duraklarında (kırmızı rota) ve geniş sarı çizgili 'bus stop clearway'lerde durulamaz.", ee: "You cannot stop at bus stops with a wide red line (on a red route), or at bus stop clearways marked with a wide yellow line." },
  { t: "fill", s: 7, q: "Tiredness can have a similar effect on a driver as ___.",
    o: ["drinking alcohol", "drinking water", "eating a meal", "listening to music"],
    tr: "Yorgunluk sürücü üzerinde ___ benzer bir etki yapabilir.",
    e: "Yorgunluk alkol gibi etkiler ve ölüm veya ağır yaralanmaya yol açabilir. Düzenli mola planlayın.", ee: "Tiredness affects you like alcohol and can cause death or serious injury. Plan regular breaks." },
  { t: "fill", s: 7, q: "Annex 6 of the Highway Code says windscreens and windows must be kept clean and free from ___.",
    o: ["obstructions to vision", "the driver's fingerprints", "rain during the winter", "passengers' belongings"],
    tr: "Karayolu Kuralları (Highway Code) Ek 6, ön camların ve camların temiz ve ___ arınmış tutulması gerektiğini söyler.",
    e: "Camlar temiz ve görüşü engelleyen şeylerden arınmış olmalı; telefon, navigasyon gibi cihazlar görüşü azaltmamalı.", ee: "Windscreens and windows must be clean and free of anything that blocks your view. Devices such as phones and sat navs must not reduce your view." },
  { t: "fill", s: 7, q: "Please ask your passengers to check before they open their door, to make sure there isn't a ___ coming.",
    o: ["cyclist", "delivery van", "police car", "bus"],
    tr: "Yolculardan kapıyı açmadan önce bir ___ gelmediğinden emin olmak için kontrol etmelerini isteyin.",
    e: "Kapı açmadan önce bisikletli kontrolü: hem yolculardan isteyin hem kendiniz yapın.​‍‌⁠", ee: "Check for cyclists before you open a door: ask your passengers to do it, and do it yourself too.​‍‌⁠" },
  { t: "fill", s: 7, q: "The clutch and brake pedals should have ___ covers.",
    o: ["anti-slip", "leather", "plastic", "colourful"],
    tr: "Debriyaj ve fren pedallarında ___ kaplama olmalıdır.",
    e: "Sürücü bölümü kontrolü: pedallarda kaymaz kaplama, sağlam direksiyon, çalışan el freni, korna, silecek ve sinyaller.", ee: "This is a driver compartment check: the pedals need anti-slip covers, and you need secure steering, a working handbrake, a horn, wipers and indicators." },
  { t: "fill", s: 8, q: "Always ask your passengers if they need any help and wait for your offer to be ___.",
    o: ["accepted", "paid for", "written down", "repeated"],
    tr: "Yolculara her zaman yardıma ihtiyaçları olup olmadığını sorun ve teklifinizin ___ bekleyin.",
    e: "Yardım teklif edin, kabul edilmesini bekleyin ve isteklerini dinleyin; herkes farklıdır.", ee: "Offer help, wait for your offer to be accepted and listen to their requests. Everyone is different." },
  { t: "fill", s: 8, q: "It is illegal to treat anyone unfairly based on a ___ characteristic.",
    o: ["protected", "personal", "physical", "popular"],
    tr: "Birine ___ bir özelliği nedeniyle haksız davranmak yasadışıdır.",
    e: "Eşitlik Yasası'ndaki korunan özellikler: yaş, engellilik, cinsiyet değişikliği, evlilik/medeni birliktelik, ırk, din/inanç, cinsiyet, cinsel yönelim, hamilelik/annelik.", ee: "The protected characteristics in the Equality Act are: age, disability, gender reassignment, marriage and civil partnership, race, religion or belief, sex, sexual orientation, and pregnancy and maternity." },
  { t: "fill", s: 9, q: "Criminal exploitation, where gangs use children to sell drugs, is also known as ___.",
    o: ["county lines", "red routes", "bus lanes", "ridesharing"],
    tr: "Çetelerin çocukları uyuşturucu satmak için kullandığı suç sömürüsüne ___ da denir.",
    e: "County lines: çeteler çocukları ve gençleri uyuşturucu satmak için ilçeler arasında taşır, telefon 'hatları' ile iletişim kurar.", ee: "County lines: gangs move children and young people between counties to sell drugs, and they keep in touch using phone ‘lines’." },
  { t: "fill", s: 9, q: "You can report concerns ___ to Crimestoppers, without giving your name.",
    o: ["anonymously", "officially", "publicly", "quickly"],
    tr: "Endişelerinizi Crimestoppers'a isminizi vermeden ___ bildirebilirsiniz.",
    e: "Crimestoppers isimsiz bir servistir (0800 555 111). Ne kadar çok bilgi verirseniz o kadar iyi.", ee: "Crimestoppers is an anonymous service (0800 555 111). The more information you give, the better." },
  { t: "fill", s: 10, q: "You should not share the ___ of one passenger with any other passenger.",
    o: ["personal details", "luggage space", "journey time", "seat belt"],
    tr: "Bir yolcunun ___ diğer yolcularla paylaşmamalısınız.",
    e: "Paylaşımlı yolculukta bir yolcunun kişisel bilgilerini diğerleriyle paylaşmayın.", ee: "In a ride-share, do not share one passenger's personal details with the others." },

  // ==== OKUMA VE ANLAMA (ek) ====
  { t: "read", s: 3, p: "Priya finishes a booking at 11pm. While checking the back seat, she finds a wallet. The passenger has already gone into a large block of flats and Priya does not know which flat.",
    q: "What should Priya do?",
    o: ["Take the wallet to her operator and tell them as soon as possible", "Knock on every door in the building until she finds the owner", "Keep the wallet at home and wait for the passenger to call her", "Leave the wallet with the security guard at the nearest station"],
    tr: "Priya gece 11'de bir işi bitiriyor. Arka koltuğu kontrol ederken bir cüzdan buluyor. Yolcu büyük bir apartmana girmiş ve Priya hangi daire olduğunu bilmiyor. Priya ne yapmalı?",
    e: "Bulunan eşyayı operatöre götürün ve yolcu zaten aramış olabileceği için hemen haber verin. Operatör eşyayı saklar ve kaydını tutar.", ee: "Take the item to your operator and tell them straight away, because the passenger may already have called. The operator will keep the item and record it." },
  { t: "read", s: 4, p: "During a journey, Tobin's passenger starts tapping his fingers, raises his voice and stares at Tobin angrily. He says the route is wrong, although it is the route the operator gave.",
    q: "What is the best thing for Tobin to do first?",
    o: ["Stay calm, listen, and explain the route without arguing", "Raise his own voice so the passenger knows who is in charge", "Stop at once and tell the passenger to get out in the road", "Ignore the passenger and drive faster to finish the journey"],
    tr: "Yolculuk sırasında Tobin'in yolcusu parmaklarını tıkırdatmaya başlıyor, sesini yükseltiyor ve Tobin'e öfkeyle bakıyor. Rotanın yanlış olduğunu söylüyor, oysa rota operatörün verdiği rota. Tobin önce ne yapmalı?",
    e: "Bunlar saldırganlık uyarı işaretleri. Sakin konuşun, sözünü kesmeden dinleyin, kaygısına cevap verin ve tartışmak yerine açıklayın. Durum kötüleşirse güvenli bir yerde durun.", ee: "These are warning signs of aggression. Speak calmly, listen without interrupting, answer their worries, and explain instead of arguing. If the situation gets worse, stop in a safe place." },
  { t: "read", s: 6, p: "At 23:30, Kemal's passenger asks him to stop on a red route so she can use a cashpoint. There are no pedestrian clearways, zig-zags or bus stops nearby.",
    q: "What can Kemal do?",
    o: ["Stop and wait for her, but for no longer than 5 minutes", "Stop and wait for as long as she needs to use the cashpoint", "Refuse, because PHVs can never wait on a red route at all", "Wait in the nearest bus stop with a wide red line instead"],
    tr: "Saat 23:30'da Kemal'in yolcusu bankamatik kullanmak için kırmızı rotada durmasını istiyor. Yakında yaya alanı, zikzak çizgi veya otobüs durağı yok. Kemal ne yapabilir?",
    e: "Kırmızı rotadaki tek istisna: 22:00-06:00 arası bankamatik için en fazla 5 dakika durulabilir. Yaya alanı, zikzak ve geniş kırmızı çizgili duraklarda asla.", ee: "This is the only exception on a red route: between 22:00 and 06:00 you can stop for no more than 5 minutes for a cashpoint. Never at pedestrian areas, zig-zag lines or bus stops with a wide red line." },
  { t: "read", s: 7, p: "Ali has been driving since 6am. At 3pm he notices he keeps yawning and once almost missed a red light. He has two more bookings before his shift ends.",
    q: "What should Ali do?",
    o: ["Stop in a safe place and take a proper break before driving again", "Open the window and turn up the radio to stay awake for the bookings", "Drive a little faster so that he can finish both bookings sooner", "Ask his next passenger to talk to him to keep him awake"],
    tr: "Ali sabah 6'dan beri araç kullanıyor. Öğleden sonra 3'te sürekli esnediğini fark ediyor ve bir kez kırmızı ışığı neredeyse kaçırıyor. Mesaisi bitmeden iki işi daha var. Ali ne yapmalı?",
    e: "Yorgunluk alkol gibi etkiler. Güvenli bir yerde durup gerçek bir mola verin; yorgunken yola devam etmeyin. Gününüzü düzenli molalarla planlayın.", ee: "Tiredness affects you like alcohol. Stop in a safe place and take a proper break. Do not carry on driving when you are tired. Plan your day with regular breaks." },
  { t: "read", s: 10, p: "Grace is driving a rideshare. Her first passenger, a young woman, asks Grace where the next passenger lives and what time he usually comes home.",
    q: "What should Grace do?",
    o: ["Politely refuse to share the other passenger's personal details", "Tell her only his street name, as long as it is in the same area", "Tell her, because both passengers are sharing the same journey", "Ask the next passenger to tell her himself when he gets in"],
    tr: "Grace paylaşımlı bir yolculuk yapıyor. İlk yolcusu olan genç bir kadın, Grace'e sıradaki yolcunun nerede oturduğunu ve genelde eve ne zaman geldiğini soruyor. Grace ne yapmalı?",
    e: "Bir yolcunun kişisel bilgilerini (adres, rutin) diğer yolcuyla asla paylaşmayın; bu bilgiler onu suça karşı savunmasız bırakabilir.", ee: "Never share one passenger's personal details (address, routine) with the other passenger. This information could make them vulnerable to crime." },
  { t: "read", s: 9, p: "Dorin picks up a 12-year-old boy for a school booking. The operator's notes say the boy's aunt will meet him at the school gate, but Dorin does not know her name.",
    q: "What should Dorin do?",
    o: ["Contact his operator to get the name of the adult meeting the child", "Drop the boy at the gate and leave, because the school is safe", "Ask the boy to point out any adult he knows when they arrive", "Take the boy back home, because the booking details are wrong"],
    tr: "Dorin bir okul işi için 12 yaşında bir çocuğu alıyor. Operatörün notunda çocuğu okul kapısında teyzesinin karşılayacağı yazıyor ama Dorin onun adını bilmiyor. Dorin ne yapmalı?",
    e: "Refakatsiz bir çocuk taşırken operatörün haberi olmalı ve çocuğu karşılayacak yetişkinin adını bilmelisiniz; bu bilgiyi operatörünüz vermeli.", ee: "When you carry an unaccompanied child, your operator must know about it and you must know the name of the adult who will meet the child. Your operator should give you this information." }
]);
